import { storage } from './storage';
import { Platform, NativeModules } from 'react-native';
// PR-C2 (Task C auto-detect): expo-localization РІС‹РґР°С‘С‚ РЅР°РґС‘Р¶РЅС‹Р№ locale
// РЅР° iOS/Android вЂ” Р»СѓС‡С€Рµ С‡РµРј NativeModules.SettingsManager.AppleLocale
// (deprecated РІ РЅРѕРІС‹С… RN). Р›РѕР°РґРёРј Р»РµРЅРёРІРѕ С‡С‚РѕР±С‹ web-bundle РЅРµ С‚Р°С‰РёР»
// РЅР°С‚РёРІРЅС‹Р№ РјРѕРґСѓР»СЊ.
let _Localization;
function getLocalization() {
  if (_Localization !== undefined) return _Localization;
  try { _Localization = require('expo-localization'); } catch { _Localization = null; }
  return _Localization;
}

const listeners = new Set();
const KEY = 'ur_lang';

// РђР»РёР°СЃС‹: СЃРёСЃС‚РµРјРЅС‹Р№ РєРѕРґ в†’ РЅР°С€ РєРѕРґ. РџРѕРґРґРµСЂР¶РёРІР°РµРј С‚РѕР»СЊРєРѕ 4 СЏР·С‹РєР°:
// RU / EN / KK (Kazakh, ISO 639-1) / ZH (Chinese, ISO 639-1).
//
// Stage 7 standardised the codes to ISO. Earlier the storage might
// have written `'KZ'` (country code, not language) or `'CN'` (also
// country code) into `ur_lang`; the loader below now redirects those
// legacy values to the proper language code so users don't lose
// their choice on upgrade.
const LANG_ALIAS = {
  ru: 'RU', rus: 'RU',
  en: 'EN', eng: 'EN',
  kk: 'KK', kaz: 'KK', 'kk-kz': 'KK',
  zh: 'ZH', 'zh-cn': 'ZH', 'zh-hans': 'ZH', 'zh-hant': 'ZH', 'zh-tw': 'ZH',
};

// Legacy persisted-value fixups. Stage 5 narrowed the set to four
// languages and renamed two of them in Stage 7 (KZв†’KK, CNв†’ZH).
// Anything else falls through to system detect / RU.
const LEGACY_LANG_FIX = {
  KZ: 'KK',
  CN: 'ZH',
};

// Sync detect at module load вЂ” best effort before async storage
// PR-C2: default fallback РЅР° 'EN' РІРјРµСЃС‚Рѕ 'RU' вЂ” РґР»СЏ РїРѕР»СЊР·РѕРІР°С‚РµР»РµР№ СЃ
// РЅРµРїРѕРґРґРµСЂР¶РёРІР°РµРјС‹Рј СЏР·С‹РєРѕРј СѓСЃС‚СЂРѕР№СЃС‚РІР° СЌС‚Рѕ РґР°С‘С‚ Р±РѕР»РµРµ СѓРЅРёРІРµСЂСЃР°Р»СЊРЅС‹Р№ first-run
// experience. RU/KK/ZH СЋР·РµСЂС‹ РІСЃС‘ СЂР°РІРЅРѕ РїРѕРїР°РґР°СЋС‚ РІ СЃРІРѕСЋ Р»РѕРєР°Р»СЊ С‡РµСЂРµР· alias.
let currentLang = (() => {
  try {
    let code = '';
    if (typeof navigator !== 'undefined' && navigator.language) {
      code = navigator.language.toLowerCase();
    }
    if (!code) return 'EN';
    const base = code.split('-')[0];
    if (LANG_ALIAS[code]) return LANG_ALIAS[code];
    if (LANG_ALIAS[base]) return LANG_ALIAS[base];
    return 'EN'; // unsupported в†’ EN
  } catch { return 'EN'; }
})();

function detectSystemLang() {
  let code;
  try {
    // PR-C2: РїСЂРµРґРїРѕС‡РёС‚Р°РµРј expo-localization (Localization.getLocales() РІ
    // SDK 52, РёР»Рё Localization.locale РІ legacy). Р­С‚Рѕ СЂР°Р±РѕС‚Р°РµС‚ РЅР° РЅРѕРІС‹С…
    // iOS / Android Р±РµР· NativeModules deprecation warnings.
    if (Platform.OS !== 'web') {
      const Loc = getLocalization();
      if (Loc) {
        try {
          // SDK 52 API: getLocales() РІРѕР·РІСЂР°С‰Р°РµС‚ array of { languageTag, вЂ¦ }
          const locales = Loc.getLocales?.();
          if (Array.isArray(locales) && locales.length && locales[0].languageTag) {
            code = String(locales[0].languageTag).toLowerCase();
          }
        } catch {}
        if (!code && Loc.locale) {
          code = String(Loc.locale).toLowerCase().replace('_', '-');
        }
      }
    }
    if (!code) {
      if (Platform.OS === 'web' && typeof navigator !== 'undefined') {
        code = (navigator.language || navigator.userLanguage || '').toLowerCase();
      } else {
        const locale =
          NativeModules.SettingsManager?.settings?.AppleLocale ||
          NativeModules.SettingsManager?.settings?.AppleLanguages?.[0] ||
          NativeModules.I18nManager?.localeIdentifier ||
          '';
        code = locale.toLowerCase().replace('_', '-');
      }
    }
  } catch {
    code = '';
  }
  if (!code) return null;
  // РїСЂРѕР±СѓРµРј РїРѕР»РЅС‹Р№ РєРѕРґ, РїРѕС‚РѕРј РѕСЃРЅРѕРІСѓ
  if (LANG_ALIAS[code]) return LANG_ALIAS[code];
  const base = code.split('-')[0];
  if (LANG_ALIAS[base]) return LANG_ALIAS[base];
  return null;
}

// Load saved language on start; РµСЃР»Рё РЅРµ РІС‹Р±СЂР°РЅ вЂ” Р°РІС‚Рѕ РёР· СЃРёСЃС‚РµРјС‹.
// PR-C2: РµСЃР»Рё detect РЅРёС‡РµРіРѕ РЅРµ РЅР°С€С‘Р» вЂ” СѓСЃС‚Р°РЅР°РІР»РёРІР°РµРј EN (СѓРЅРёРІРµСЂСЃР°Р»СЊРЅС‹Р№
// fallback РґР»СЏ РїСЂРёРіСЂР°РЅРёС‡РЅС‹С… РїРѕР»СЊР·РѕРІР°С‚РµР»РµР№ СЃ СЌРєР·РѕС‚РёС‡РµСЃРєРёРјРё locale).
(async () => {
  let saved = await storage.get(KEY);
  // Legacy fix-up: rewrite `KZ` в†’ `KK`, `CN` в†’ `ZH` for users
  // upgrading from a Stage 5 build.
  if (saved && LEGACY_LANG_FIX[saved]) {
    saved = LEGACY_LANG_FIX[saved];
    storage.set(KEY, saved);
  }
  if (saved && translations[saved]) {
    currentLang = saved;
  } else {
    const sys = detectSystemLang();
    if (sys && translations[sys]) {
      currentLang = sys;
      storage.set(KEY, sys); // СЃРѕС…СЂР°РЅСЏРµРј РІС‹Р±РѕСЂ Р°РІС‚Рѕ
    } else if (!translations[currentLang]) {
      currentLang = 'EN';
      storage.set(KEY, 'EN');
    }
  }
  syncDocumentLanguage(currentLang);
  listeners.forEach(cb => cb(currentLang));
})();

const HTML_LANG = { RU: 'ru', KK: 'kk', ZH: 'zh-CN', EN: 'en' };

const syncDocumentLanguage = (lang) => {
  // The browser translator was appearing above the Chinese UI because the
  // document stayed marked as English. Native builds have no `document`.
  if (typeof document !== 'undefined' && document.documentElement) {
    document.documentElement.lang = HTML_LANG[lang] || 'en';
  }
};

export const setLanguage = (lang) => {
  currentLang = translations[lang] ? lang : 'EN';
  storage.set(KEY, currentLang);
  syncDocumentLanguage(currentLang);
  listeners.forEach(cb => cb(currentLang));
};

export const getLanguage = () => currentLang;

export const subscribeToLanguage = (cb) => {
  listeners.add(cb);
  return () => listeners.delete(cb);
};

export const t = (key) => {
  const lang = translations[currentLang];
  if (lang && lang[key]) return lang[key];
  return translations.RU[key] || key;
};

// РЎРєР»РѕРЅРµРЅРёРµ РґР»СЏ СЂСѓСЃСЃРєРѕРіРѕ: 1 СЃС‚Р°РІРєР°, 2 СЃС‚Р°РІРєРё, 5 СЃС‚Р°РІРѕРє
function pluralRu(n, one, few, many) {
  const abs = Math.abs(n) % 100;
  const last = abs % 10;
  if (abs >= 11 && abs <= 14) return many;
  if (last === 1) return one;
  if (last >= 2 && last <= 4) return few;
  return many;
}

export const formatBids = (count) => {
  const n = count || 0;
  // Р•РґРёРЅР°СЏ С‚РµСЂРјРёРЅРѕР»РѕРіРёСЏ: В«РїСЂРµРґР»РѕР¶РµРЅРёРµВ» (РєР°Рє РІ РєРѕР»РѕРєРѕР»Рµ В«РќРѕРІРѕРµ РїСЂРµРґР»РѕР¶РµРЅРёРµВ» Рё
  // РІРєР»Р°РґРєРµ В«РџСЂРµРґР»РѕР¶РµРЅРёСЏВ»), Р° РЅРµ В«СЃС‚Р°РІРєР°В» вЂ” РѕРґРЅРѕ СЃР»РѕРІРѕ РІРѕ РІСЃС‘Рј С„Р»РѕСѓ СЃРґРµР»РєРё.
  if (currentLang === 'RU' || currentLang === 'KK' || currentLang === 'KG') {
    return `${n} ${pluralRu(n, 'РїСЂРµРґР»РѕР¶РµРЅРёРµ', 'РїСЂРµРґР»РѕР¶РµРЅРёСЏ', 'РїСЂРµРґР»РѕР¶РµРЅРёР№')}`;
  }
  return `${n} ${t('bids')}`;
};

export const formatStatus = (status) => {
  const key = `status_${status}`;
  const val = t(key);
  return val !== key ? val : t('status_unknown');
};

export const formatTruckType = (type) => {
  if (!type) return t('cargo_type_unknown');
  const val = t(type);
  return val !== type ? val : type;
};

export const formatCargoType = (type) => {
  if (!type) return t('cargo_type_unknown');
  const val = t(type);
  return val !== type ? val : type;
};

export default translations;
